import { View, Text } from 'react-native'
import { colors, useTheme } from '@/theme'

type NumberBadgeProps = {
	radius?: number
	position?: 'top-right' | 'top-left' | 'bottom-right' | 'bottom-left'
	offset?: number
	value: number
}

export const NumberBadge = ({
	radius = 10,
	position = 'top-right',
	offset = 0,
	value
}: NumberBadgeProps) => {
	const { theme } = useTheme()
	const positionStyle = (() => {
		switch (position) {
			case 'top-right':
				return { top: offset, right: offset }
			case 'top-left':
				return { top: offset, left: offset }
			case 'bottom-right':
				return { bottom: offset, right: offset }
			case 'bottom-left':
				return { bottom: offset, left: offset }
		}
	})()

	return (
		<View
			style={{
				display: value > 0 ? 'flex' : 'none',
				backgroundColor: colors[theme].gray[900],
				width: radius * 2,
				height: radius * 2,
				borderRadius: 99,
				justifyContent: 'center',
				alignItems: 'center',
				position: 'absolute',
				...positionStyle
			}}
		>
			<Text
				style={{
					color: colors[theme].gray[25],
					fontSize: 14,
					fontWeight: '500'
				}}
			>
				{value}
			</Text>
		</View>
	)
}
